import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';
import '../../../styles/GlobalStyles.css';

const AttendeeDashboard = () => {
  const [events, setEvents]   = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState(null);

  // fetch events and registration/payment flags
  const fetchEvents = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('token');
      const res   = await axios.get(
        '/api/attendee/events',                // proxy will forward to localhost:5000
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setEvents(res.data.events);
      setError(null);
    } catch {
      setError('Failed to fetch events');
    } finally {
      setLoading(false);
    }
  };

  useEffect(fetchEvents, []);

  // register → refresh
  const handleRegister = async (id) => {
    try {
      const token = localStorage.getItem('token');
      await axios.post(
        '/api/attendee/register',
        { eventId: id },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      fetchEvents();
    } catch {
      alert('Registration failed');
    }
  };

  // pay → refresh
  const handlePay = async (id) => {
    try {
      const token = localStorage.getItem('token');
      await axios.post(
        `/api/attendee/pay/${id}`,
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );
      fetchEvents();
    } catch {
      alert('Payment failed');
    }
  };

  // categorize
  const upcoming    = events.filter(e => !e.isRegistered);
  const registered  = events.filter(e => e.isRegistered && !e.hasPaid);
  const paid        = events.filter(e => e.hasPaid);

  return (
    <div className="container">
      <div className="card">
        <h2>Attendee Dashboard</h2>

        {/* Upcoming */}
        <section>
          <h3>Upcoming Events</h3>
          {loading ? (
            <p>Loading…</p>
          ) : error ? (
            <p style={{ color: 'red' }}>{error}</p>
          ) : upcoming.length === 0 ? (
            <p>No upcoming events.</p>
          ) : (
            <ul style={{ listStyle: 'none', padding: 0 }}>
              {upcoming.map(evt => (
                <li key={evt.id} style={{ marginBottom: '1.5rem' }}>
                  <strong>{evt.title}</strong><br/>
                  <small>{new Date(evt.date).toLocaleString()}</small><br/>
                  <button className="btn" onClick={() => handleRegister(evt.id)}>
                    Register
                  </button>
                </li>
              ))}
            </ul>
          )}
        </section>

        {/* Pending Payment */}
        <section style={{ marginTop: '2rem' }}>
          <h3>Pending Payment</h3>
          {registered.length === 0 ? (
            <p>No registrations pending payment.</p>
          ) : (
            <ul style={{ listStyle: 'none', padding: 0 }}>
              {registered.map(evt => (
                <li key={evt.id} style={{ marginBottom: '1.5rem' }}>
                  <strong>{evt.title}</strong><br/>
                  <small>{new Date(evt.date).toLocaleString()}</small><br/>
                  <button className="btn" onClick={() => handlePay(evt.id)}>
                    Pay Now
                  </button>
                </li>
              ))}
            </ul>
          )}
        </section>

        {/* Paid */}
        <section style={{ marginTop: '2rem' }}>
          <h3>Registered & Paid</h3>
          {paid.length === 0 ? (
            <p>No paid events yet.</p>
          ) : (
            <ul style={{ listStyle: 'none', padding: 0 }}>
              {paid.map(evt => (
                <li key={evt.id} style={{ marginBottom: '1.5rem' }}>
                  <strong>{evt.title}</strong><br/>
                  <small>{new Date(evt.date).toLocaleString()}</small><br/>
                  <Link to={`/join?link=${encodeURIComponent(roomName)}`}>
  <button className="btn">Join Session</button>
</Link>

                </li>
              ))}
            </ul>
          )}
        </section>
      </div>
    </div>
  );
};

export default AttendeeDashboard;
